node <<'NODE'
const fs = require('node:fs');
const assert = require('node:assert/strict');
const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const registry = readJson('fleet/registry.json');
const egress = readJson('fleet/egress.json');
const replay = readJson('fleet/replay.json');
const orders = readJson('fleet/change-orders.json').orders;
const plan = readJson('rollout/plan.json');

const trafficRows = fs.readFileSync('fleet/traffic.csv', 'utf8').trim().split(/\r?\n/);
const header = trafficRows.shift().split(',');
assert.deepEqual(header, ['site', 'peak1', 'peak2']);
const peaks = Object.fromEntries(trafficRows.map((line) => {
  const [site, p1, p2] = line.split(',');
  return [site, [Number(p1), Number(p2)]];
}));
const sites = Object.keys(registry.sites);
assert.deepEqual(Object.keys(peaks).sort(), sites.slice().sort(), 'traffic must cover all registry sites');
const windows = ['W1', 'W2'];
const windowIndex = Object.fromEntries(windows.map((w, i) => [w, i + 1]));

function afterWindowIndex(label) {
  const m = /^after (W\d+)$/.exec(label);
  assert.ok(m, `unexpected effective value: ${label}`);
  return windowIndex[m[1]] + 1;
}

// Resolve a site's build in each window from the registry plan and any signed order that supersedes it.
function buildsFor(site) {
  const base = registry.sites[site].build;
  const planned = registry.planned.find((p) => p.site === site);
  const signed = orders.find((o) => o.site === site && o.build && o.effective);
  let change = null;
  if (signed && signed.supersedes === 'registry planned upgrade') {
    change = { build: signed.build, effectiveAt: afterWindowIndex(signed.effective), order: signed.id };
  } else if (planned) {
    change = { build: planned.build, effectiveAt: afterWindowIndex('after ' + planned.after) };
  }
  const out = {};
  for (const w of windows) out[w] = change && windowIndex[w] >= change.effectiveAt ? change.build : base;
  return out;
}

const builds = Object.fromEntries(sites.map((s) => [s, buildsFor(s)]));
assert.equal(builds.Dune.W1, 'R1');
assert.equal(builds.Dune.W2, 'R1', 'OPS-17 supersedes Dune after-W1 upgrade');

const required = replay.requiredReadings;
const passing = new Set();
for (const [build, obs] of Object.entries(Object.groupBy(replay.observations, (o) => o.build))) {
  const omitted = obs.find((o) => o.limit === 'omitted');
  const zero = obs.find((o) => o.limit === 'zero');
  if (omitted && zero && omitted.decoded >= required && zero.decoded >= required) passing.add(build);
}
assert.deepEqual([...passing].sort(), ['R2', 'R3']);

const siteUnits = Object.fromEntries(sites.map((s) => [s, Math.ceil(Math.max(...peaks[s]) * egress.headroomFactor)]));
assert.deepEqual(siteUnits, { Alder: 5, Birch: 4, Cedar: 4, Dune: 3 });
assert.deepEqual(plan.siteUnits, siteUnits, 'siteUnits must match recomputed values and cover all sites');
for (const [s, u] of Object.entries(plan.siteUnits)) assert.ok(Number.isInteger(u) && u > 0, `${s} units must be a positive integer`);

for (const w of windows) {
  const shared = orders
    .filter((o) => o.window === w && Number.isInteger(o.reservedUnits))
    .reduce((sum, o) => sum + o.reservedUnits, 0);
  const available = egress.grossUnits[w] - shared;
  assert.ok(Number.isInteger(available) && available >= 0);
  const eligible = sites.filter((s) => passing.has(builds[s][w]));
  const subsets = [];
  for (let mask = 0; mask < (1 << eligible.length); mask++) {
    const selected = eligible.filter((_, i) => mask & (1 << i));
    const units = selected.reduce((sum, s) => sum + siteUnits[s], 0);
    if (units <= available) subsets.push({
      selected: selected.sort(),
      units,
      priority: selected.reduce((sum, s) => sum + registry.sites[s].priority, 0),
    });
  }
  const best = Math.max(...subsets.map((x) => x.priority));
  const optimal = subsets.filter((x) => x.priority === best);
  const p = plan.windows[w];
  assert.ok(p, `missing ${w}`);
  assert.deepEqual([...p.grpc].sort(), [...p.grpc].sort(), `${w} grpc must be an array`);
  assert.equal(new Set([...p.grpc, ...p.rest]).size, sites.length, `${w} must partition sites`);
  assert.deepEqual([...p.grpc, ...p.rest].sort(), sites.slice().sort(), `${w} arrays must cover exactly all sites`);
  assert.ok(p.grpc.every((s) => eligible.includes(s)), `${w} selected an ineligible site`);
  const chosen = p.grpc.slice().sort();
  const chosenUnits = chosen.reduce((sum, s) => sum + siteUnits[s], 0);
  const chosenPriority = chosen.reduce((sum, s) => sum + registry.sites[s].priority, 0);
  assert.equal(p.used, chosenUnits, `${w} used mismatch`);
  assert.equal(p.available, available, `${w} available mismatch`);
  assert.equal(p.priority, chosenPriority, `${w} priority mismatch`);
  assert.ok(Number.isInteger(p.used) && Number.isInteger(p.available) && Number.isInteger(p.priority), `${w} integers required`);
  assert.ok(chosenPriority === best, `${w} is not optimal`);
  assert.ok(optimal.some((o) => o.selected.join(',') === chosen.join(',')), `${w} chosen set is not an optimal set`);
  console.log(`${w}: eligible=${eligible.join(',')} available=${available} grpc=${p.grpc.join(',')} used=${p.used} priority=${p.priority} optimalPriority=${best}`);
}

assert.deepEqual(Object.keys(plan.windows).sort(), ['W1', 'W2']);
assert.deepEqual(Object.keys(plan.siteUnits).sort(), sites.slice().sort());
console.log('PASS: plan.json matches records, partitions all sites, respects capacity, and both selections are optimal.');
